CREATE TABLE IF NOT EXISTS routes(id INTEGER PRIMARY KEY, source TEXT NOT NULL, topic INTEGER NOT NULL DEFAULT 0, dest TEXT NOT NULL, dest_topic INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'all', enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(source,topic,dest,dest_topic));
CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY, route_id INTEGER NOT NULL REFERENCES routes(id), message_id INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'queued', due INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, UNIQUE(route_id,message_id));
CREATE INDEX IF NOT EXISTS jobs_ready ON jobs(state,due,id);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topics(chat TEXT NOT NULL, thread INTEGER NOT NULL, title TEXT, PRIMARY KEY(chat,thread));
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY, body TEXT NOT NULL);
